using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using ConnectQuick.WindowsHost.Crypto;
using ConnectQuick.WindowsHost.Protocol;
using ConnectQuick.WindowsHost.Session;
using NSec.Cryptography;

namespace ConnectQuick.WindowsHost.Tests;

/// <summary>
/// The Windows implementation must reproduce every value in Protocol/test-vectors/session-vectors.json,
/// which is generated by the TypeScript reference. Passing here means a Host and a Controller (or the
/// reference peer) derive the same keys and can open each other's frames.
/// </summary>
public sealed class SessionVectorsTests
{
    private static readonly JsonElement V = VectorFiles.Load("session-vectors.json");

    private static Key X25519(string privateB64Url)
    {
        var creation = new KeyCreationParameters { ExportPolicy = KeyExportPolicies.AllowPlaintextExport };
        return Key.Import(KeyAgreementAlgorithm.X25519, CryptoUtil.FromBase64Url(privateB64Url), KeyBlobFormat.RawPrivateKey, creation);
    }

    private static string[] Permissions() =>
        V.GetProperty("session").GetProperty("permissions").EnumerateArray().Select(e => e.GetString()!).ToArray();

    private static (byte[] C2H, byte[] H2C) Keys(out string hostId, out string deviceId, out string sessionId)
    {
        var host = V.GetProperty("identities").GetProperty("host");
        var controller = V.GetProperty("identities").GetProperty("controller");
        hostId = host.S("expectedDeviceId");
        deviceId = controller.S("expectedDeviceId");
        sessionId = V.GetProperty("session").S("sessionId");
        var eph = V.GetProperty("ephemeral");
        using var c = X25519(eph.GetProperty("controller").S("privateB64Url"));
        var cPub = eph.GetProperty("controller").S("publicB64Url");
        var hPub = eph.GetProperty("host").S("publicB64Url");
        var transcript = SessionCrypto.TranscriptHash(sessionId, hostId, deviceId, cPub, hPub, Permissions());
        return SessionCrypto.DeriveKeys(SessionCrypto.SharedSecret(c, hPub), transcript);
    }

    [Fact]
    public void Public_keys_derive_from_the_private_seeds()
    {
        var eph = V.GetProperty("ephemeral");
        foreach (var who in new[] { "controller", "host" })
        {
            using var k = X25519(eph.GetProperty(who).S("privateB64Url"));
            Assert.Equal(eph.GetProperty(who).S("publicB64Url"), CryptoUtil.ExportPublicB64Url(k));
        }
    }

    [Fact]
    public void Signed_messages_and_signatures_match_the_reference()
    {
        var ids = V.GetProperty("identities");
        var session = V.GetProperty("session");
        var eph = V.GetProperty("ephemeral");
        var exp = V.GetProperty("expected");
        var hostId = ids.GetProperty("host").S("expectedDeviceId");
        var deviceId = ids.GetProperty("controller").S("expectedDeviceId");
        var cPub = eph.GetProperty("controller").S("publicB64Url");
        var hPub = eph.GetProperty("host").S("publicB64Url");
        var sessionId = session.S("sessionId");

        var connect = SessionCrypto.ConnectMessage(sessionId, hostId, deviceId, cPub, session.GetProperty("issuedAt").GetInt64());
        Assert.Equal(exp.S("connectMessage"), connect);
        using var controllerKey = CryptoUtil.ImportEd25519PrivateKey(CryptoUtil.FromBase64Url(ids.GetProperty("controller").S("privateJwkD")));
        Assert.Equal(exp.S("connectSigB64Url"), CryptoUtil.SignEd25519(controllerKey, Encoding.UTF8.GetBytes(connect)));

        var accept = SessionCrypto.AcceptMessage(sessionId, hostId, deviceId, cPub, hPub, Permissions());
        Assert.Equal(exp.S("acceptMessage"), accept);
        using var hostKey = CryptoUtil.ImportEd25519PrivateKey(CryptoUtil.FromBase64Url(ids.GetProperty("host").S("privateJwkD")));
        Assert.Equal(exp.S("acceptSigB64Url"), CryptoUtil.SignEd25519(hostKey, Encoding.UTF8.GetBytes(accept)));
        Assert.True(CryptoUtil.VerifyEd25519(ids.GetProperty("host").S("publicKeyB64Url"), Encoding.UTF8.GetBytes(accept), exp.S("acceptSigB64Url")));
    }

    [Fact]
    public void Shared_secret_transcript_and_keys_match_and_both_sides_agree()
    {
        var keys = Keys(out _, out _, out _);
        var exp = V.GetProperty("expected");
        Assert.Equal(exp.S("keyC2HB64Url"), CryptoUtil.ToBase64Url(keys.C2H));
        Assert.Equal(exp.S("keyH2CB64Url"), CryptoUtil.ToBase64Url(keys.H2C));

        var eph = V.GetProperty("ephemeral");
        using var h = X25519(eph.GetProperty("host").S("privateB64Url"));
        var fromHost = SessionCrypto.SharedSecret(h, eph.GetProperty("controller").S("publicB64Url"));
        Assert.Equal(exp.S("sharedSecretB64Url"), CryptoUtil.ToBase64Url(fromHost));
    }

    [Fact]
    public void Every_reference_frame_opens_and_our_own_sealing_reproduces_it()
    {
        var keys = Keys(out _, out _, out var sessionId);
        foreach (var f in V.GetProperty("frames").EnumerateArray())
        {
            var c2h = f.S("direction") == "c2h";
            var receiver = c2h ? SessionChannel.ForHost(sessionId, keys) : SessionChannel.ForController(sessionId, keys);
            var sender = c2h ? SessionChannel.ForController(sessionId, keys) : SessionChannel.ForHost(sessionId, keys);
            var seq = f.GetProperty("seq").GetInt64();
            var ct = f.S("ct");
            Assert.Equal(f.S("plaintext"), Encoding.UTF8.GetString(receiver.Open(seq, ct)));
            Assert.Equal(ct, sender.Seal(Encoding.UTF8.GetBytes(f.S("plaintext")), seq).Ct);
        }
    }

    [Fact]
    public void Tampered_reflected_and_resequenced_frames_are_rejected()
    {
        var keys = Keys(out _, out _, out var sessionId);
        var neg = V.GetProperty("negative");
        var t = neg.GetProperty("tamperedFrame");
        Assert.Throws<AuthenticationTagMismatchException>(() => SessionChannel.ForHost(sessionId, keys).Open(t.GetProperty("seq").GetInt64(), t.S("ctWithFlippedBit")));
        var r = neg.GetProperty("wrongDirection");
        Assert.ThrowsAny<CryptographicException>(() => SessionChannel.ForController(sessionId, keys).Open(r.GetProperty("seq").GetInt64(), r.S("ct")));
        var w = neg.GetProperty("wrongSeq");
        Assert.ThrowsAny<CryptographicException>(() => SessionChannel.ForHost(sessionId, keys).Open(w.GetProperty("presentedSeq").GetInt64(), w.S("ct")));
    }

    [Fact]
    public void Replays_and_out_of_order_frames_are_rejected_after_a_valid_one()
    {
        var keys = Keys(out _, out _, out var sessionId);
        var tx = SessionChannel.ForController(sessionId, keys);
        var rx = SessionChannel.ForHost(sessionId, keys);
        var a = tx.Seal("{}"u8);
        var b = tx.Seal("{}"u8);
        rx.Open(b.Seq, b.Ct);
        Assert.ThrowsAny<CryptographicException>(() => rx.Open(a.Seq, a.Ct));
        Assert.ThrowsAny<CryptographicException>(() => rx.Open(b.Seq, b.Ct));
        Assert.Throws<InvalidOperationException>(() => tx.Seal("{}"u8, 4294967296));
    }

    [Fact]
    public void A_low_order_peer_key_is_refused()
    {
        using var own = CryptoUtil.CreateX25519Ephemeral();
        var zero = CryptoUtil.ToBase64Url(new byte[32]);
        Assert.ThrowsAny<CryptographicException>(() => SessionCrypto.SharedSecret(own, zero));
        Assert.ThrowsAny<CryptographicException>(() => SessionCrypto.SharedSecret(own, CryptoUtil.ToBase64Url(new byte[16])));
    }
}

public sealed class InnerMessageVectorsTests
{
    private static readonly JsonElement V = VectorFiles.Load("inner-message-vectors.json");

    [Fact]
    public void Every_valid_message_is_accepted()
    {
        var valid = V.GetProperty("valid").EnumerateArray().ToList();
        Assert.True(valid.Count >= 40);
        foreach (var m in valid)
        {
            var r = InnerMessages.Parse(m.S("json"));
            Assert.True(r.Ok, $"{m.S("name")} => {r.Rejection}");
        }
    }

    [Fact]
    public void Every_invalid_message_is_rejected_with_the_same_class_as_the_reference()
    {
        var expected = new Dictionary<string, InnerRejection>
        {
            ["too_large"] = InnerRejection.TooLarge,
            ["malformed_json"] = InnerRejection.MalformedJson,
            ["not_an_object"] = InnerRejection.NotAnObject,
            ["missing_type"] = InnerRejection.MissingType,
            ["unknown_type"] = InnerRejection.UnknownType,
            ["schema"] = InnerRejection.Schema,
        };
        var invalid = V.GetProperty("invalid").EnumerateArray().ToList();
        Assert.True(invalid.Count >= 40);
        foreach (var m in invalid)
        {
            var r = InnerMessages.Parse(m.S("json"));
            Assert.True(expected[m.S("reason")] == r.Rejection, $"{m.S("name")}: expected {m.S("reason")}, got {r.Rejection}");
        }
    }

    [Fact]
    public void Every_type_in_the_schema_has_a_valid_vector()
    {
        var covered = V.GetProperty("valid").EnumerateArray()
            .Select(m => JsonDocument.Parse(m.S("json")).RootElement.GetProperty("t").GetString()!)
            .ToHashSet();
        foreach (var t in InnerMessages.KnownTypes) Assert.Contains(t, covered);
    }

    [Fact]
    public void Serialize_enforces_the_size_limit_before_encryption()
    {
        var big = new string('x', InnerMessages.MaxInnerBytes);
        Assert.Throws<InvalidOperationException>(() => InnerMessages.Serialize("rtc.offer", new() { ["sdp"] = big }));
    }
}
